import { EventBus } from '../events/bus';
import { DomainEvent } from '../events/types';
import { DatabaseManager } from '../db';

export class Coordinator {
    private eventBus: EventBus;
    private db: DatabaseManager;

    private evaluateQueueTimeout: NodeJS.Timeout | null = null;
    private isEvaluating = false;
    private aiJobSightingTimes: Record<string, number> = {};

    constructor(eventBus: EventBus, db: DatabaseManager) {
        this.eventBus = eventBus;
        this.db = db;
        this.registerReactors();

        // Kick off evaluation on boot to resume interrupted tasks
        this.triggerEvaluateQueue();
    }

    private registerReactors() {
        this.eventBus.subscribe('MediaDiscovered', this.onMediaDiscovered.bind(this));

        // Progression triggers
        this.eventBus.subscribe('PreviewGenerated', this.onPreviewGenerated.bind(this));
        this.eventBus.subscribe('FacesDetected', this.onFacesDetected.bind(this));
        this.eventBus.subscribe('FaceEmbeddingGenerated', this.onFaceEmbeddingGenerated.bind(this));

        // Worker completion unblocks the queue
        this.eventBus.subscribe('JobCompleted', this.onJobCompleted.bind(this));
        this.eventBus.subscribe('JobFailed', this.onJobCompleted.bind(this));
    }

    private triggerEvaluateQueue() {
        if (this.evaluateQueueTimeout) {
            clearTimeout(this.evaluateQueueTimeout);
        }
        this.evaluateQueueTimeout = setTimeout(() => {
            this.evaluateQueueTimeout = null;
            this.evaluateQueue();
        }, 500); // Debounce to prevent hammering DB on burst events
    }

    // --- Enqueueing Workflows ---

    private onMediaDiscovered(event: DomainEvent) {
        if (event.type !== 'MediaDiscovered') return;
        this.db.getDb().prepare(`INSERT OR IGNORE INTO task_queue (media_id, pipeline_stage) VALUES (?, 'previews')`).run(event.mediaId);
        this.triggerEvaluateQueue();
    }

    private onPreviewGenerated(event: DomainEvent) {
        if (event.type !== 'PreviewGenerated') return;
        this.db.getDb().transaction(() => {
            this.db.getDb().prepare(`UPDATE task_queue SET status = 'completed' WHERE media_id = ? AND pipeline_stage = 'previews'`).run(event.mediaId);
            this.db.getDb().prepare(`INSERT OR IGNORE INTO task_queue (media_id, pipeline_stage) VALUES (?, 'detection')`).run(event.mediaId);
        })();
        this.triggerEvaluateQueue();
    }

    private onFacesDetected(event: DomainEvent) {
        if (event.type !== 'FacesDetected') return;
        this.db.getDb().transaction(() => {
            this.db.getDb().prepare(`UPDATE task_queue SET status = 'completed' WHERE media_id = ? AND pipeline_stage = 'detection'`).run(event.mediaId);
            if (event.faceCount > 0) {
                this.db.getDb().prepare(`INSERT OR IGNORE INTO task_queue (media_id, pipeline_stage) VALUES (?, 'recognition')`).run(event.mediaId);
            }
        })();
        this.triggerEvaluateQueue();
    }

    private onFaceEmbeddingGenerated(event: DomainEvent) {
        if (event.type !== 'FaceEmbeddingGenerated') return;
        // Mark recognition completed per face. Since we dispatch per image batch, it's safe to mark the 'recognition' item completed upon the first face's embedding (or all, the UPDATE is idempotent)
        this.db.getDb().prepare(`UPDATE task_queue SET status = 'completed' WHERE media_id = ? AND pipeline_stage = 'recognition'`).run(event.mediaId);
        this.triggerEvaluateQueue();
    }

    private onJobCompleted(event: DomainEvent) {
        // Any job finishing means we should check if there is more work to give the generic workers.
        this.triggerEvaluateQueue();
    }

    // --- Smart Evaluation Loop ---

    private evaluateQueue() {
        if (this.isEvaluating) return;
        this.isEvaluating = true;
        try {
            // 1. High-Priority Jump (Single Photo View)
            const highPriorityRows = this.db.getDb().prepare(`
                SELECT media_id, pipeline_stage 
                FROM task_queue
                WHERE status = 'pending' AND priority > 0
                ORDER BY priority DESC, created_at ASC
                LIMIT 50
            `).all() as any[];

            if (highPriorityRows.length > 0) {
                this.dispatchTasks(highPriorityRows);
                return; // Return early, let high-priority finish before touching bulk
            }

            // 2. Strict Bulk Processing Sequence
            // A. Previews (Highest Bulk Priority)
            const activePreviews = this.db.getDb().prepare(`SELECT count(*) as count FROM task_queue WHERE status IN ('pending', 'processing') AND pipeline_stage = 'previews'`).get() as { count: number };
            if (activePreviews.count > 0) {
                const pendingBatch = this.db.getDb().prepare(`
                    SELECT media_id, pipeline_stage FROM task_queue WHERE status = 'pending' AND pipeline_stage = 'previews' ORDER BY created_at ASC LIMIT 100
                `).all() as any[];
                if (pendingBatch.length > 0) this.dispatchTasks(pendingBatch);
                return; // BLOCK AI STAGES WHILE PREVIEWS PEND OR PROCESS
            }

            // B. Face Detection (Heavy Task)
            const activeDetection = this.db.getDb().prepare(`SELECT count(*) as count FROM task_queue WHERE status IN ('pending', 'processing') AND pipeline_stage = 'detection'`).get() as { count: number };
            if (activeDetection.count > 0) {
                const pendingDetectionCount = this.db.getDb().prepare(`SELECT count(*) as count FROM task_queue WHERE status = 'pending' AND pipeline_stage = 'detection'`).get() as { count: number };
                if (pendingDetectionCount.count > 0 && this.shouldTriggerHeavyTask('detection', pendingDetectionCount.count)) {
                    const batch = this.db.getDb().prepare(`
                        SELECT media_id, pipeline_stage FROM task_queue WHERE status = 'pending' AND pipeline_stage = 'detection' ORDER BY created_at ASC LIMIT 100
                    `).all() as any[];
                    this.dispatchTasks(batch);
                }
                return; // BLOCK RECOGNITION WHILE DETECTION PENDS OR PROCESSES
            } else {
                delete this.aiJobSightingTimes['detection'];
            }

            // C. Face Recognition (Heavy Task)
            const activeRecognition = this.db.getDb().prepare(`SELECT count(*) as count FROM task_queue WHERE status IN ('pending', 'processing') AND pipeline_stage = 'recognition'`).get() as { count: number };
            if (activeRecognition.count > 0) {
                const pendingRecognitionCount = this.db.getDb().prepare(`SELECT count(*) as count FROM task_queue WHERE status = 'pending' AND pipeline_stage = 'recognition'`).get() as { count: number };
                if (pendingRecognitionCount.count > 0 && this.shouldTriggerHeavyTask('recognition', pendingRecognitionCount.count)) {
                    const batch = this.db.getDb().prepare(`
                        SELECT media_id, pipeline_stage FROM task_queue WHERE status = 'pending' AND pipeline_stage = 'recognition' ORDER BY created_at ASC LIMIT 100
                    `).all() as any[];
                    this.dispatchTasks(batch);
                }
                return; // BLOCK CLUSTERING
            } else {
                delete this.aiJobSightingTimes['recognition'];
            }

            // D. Clustering (Trigger if anything changed recently? Defer to main.ts or manual for now, as it's full-system)
            // Can be implemented similarly via a 'clustering' pending flag.

        } finally {
            this.isEvaluating = false;
        }
    }

    private shouldTriggerHeavyTask(stage: string, count: number): boolean {
        const BATCH_THRESHOLD = 20; // Only spin up model when 20 items are queued
        const MAX_WAIT_MS = 20000;  // OR if 20s have passed since the first item appeared

        if (count >= BATCH_THRESHOLD) return true;

        const now = Date.now();
        if (!this.aiJobSightingTimes[stage]) {
            this.aiJobSightingTimes[stage] = now;
            return false;
        }

        if (now - this.aiJobSightingTimes[stage] >= MAX_WAIT_MS) {
            return true;
        }

        return false;
    }

    private dispatchTasks(rows: any[]) {
        if (rows.length === 0) return;

        const mediaIdsByStage: Record<string, string[]> = {};

        // Mark as processing atomically
        const stmt = this.db.getDb().prepare(`UPDATE task_queue SET status = 'processing' WHERE media_id = ? AND pipeline_stage = ?`);
        this.db.getDb().transaction(() => {
            for (const row of rows) {
                stmt.run(row.media_id, row.pipeline_stage);
                if (!mediaIdsByStage[row.pipeline_stage]) mediaIdsByStage[row.pipeline_stage] = [];
                mediaIdsByStage[row.pipeline_stage].push(row.media_id);
            }
        })();

        // Dispatch requests to main.ts orchestrator logic
        if (mediaIdsByStage['previews']) {
            this.eventBus.emit({
                type: 'PreviewRequested',
                mediaIds: mediaIdsByStage['previews'],
                reason: 'ingest'
            });
        }
        if (mediaIdsByStage['detection']) {
            this.eventBus.emit({
                type: 'FaceDetectionRequested',
                mediaIds: mediaIdsByStage['detection']
            });
        }
        if (mediaIdsByStage['recognition']) {
            this.eventBus.emit({
                type: 'FaceRecognitionRequested',
                mediaIds: mediaIdsByStage['recognition']
            });
        }
    }
}

import { DomainEvent } from '../events/types';

export type WorkflowDefinition = {
    trigger: DomainEvent['type'];
    action: (event: any) => Promise<DomainEvent[] | void>;
};

// This file is a placeholder for declarative workflow definitions.
// Ideally, this would be a static structure, but for now we might use it to export constants
// or types that define the shape of our workflows.

export const WORKFLOWS = {
    INGEST: 'IngestWorkflow',
    PREVIEW: 'PreviewWorkflow',
    FACE_ANALYSIS: 'FaceAnalysisWorkflow'
};

import Database from 'better-sqlite3';
import { join } from 'node:path';
import { existsSync, mkdirSync, readFileSync } from 'node:fs';

export class DatabaseManager {
  private db: Database.Database;

  constructor(storagePath: string) {
    if (!existsSync(storagePath)) {
      mkdirSync(storagePath, { recursive: true });
    }
    const dbPath = join(storagePath, 'library.db');
    this.db = new Database(dbPath);
    this.db.pragma('journal_mode = WAL');
    this.initSchema();
  }

  private initSchema() {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS assets (
        id TEXT PRIMARY KEY,
        original_path TEXT NOT NULL,
        file_hash TEXT,
        file_size INTEGER,
        width INTEGER,
        height INTEGER,
        exif_datetime TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS events (
        id TEXT PRIMARY KEY,
        type TEXT NOT NULL,
        payload TEXT NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
      );


      CREATE TABLE IF NOT EXISTS jobs (
        id TEXT PRIMARY KEY,
        stage TEXT NOT NULL,
        status TEXT NOT NULL,
        progress INTEGER DEFAULT 0,
        cancelable INTEGER DEFAULT 0,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        started_at TEXT,
        finished_at TEXT,
        total_items INTEGER DEFAULT 0,
        processed_items INTEGER DEFAULT 0,
        error_count INTEGER DEFAULT 0,
        current_item_path TEXT,
        throughput_ips REAL DEFAULT 0
      );

      CREATE TABLE IF NOT EXISTS previews (
        asset_id TEXT NOT NULL,
        size TEXT NOT NULL,
        path TEXT NOT NULL,
        version INTEGER DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (asset_id, size),
        FOREIGN KEY(asset_id) REFERENCES assets(id)
      );

      CREATE TABLE IF NOT EXISTS derived_results (
        id TEXT PRIMARY KEY,
        asset_id TEXT NOT NULL,
        task TEXT NOT NULL,
        provider TEXT NOT NULL,
        model_version TEXT,
        data JSON,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(asset_id) REFERENCES assets(id)
      );
      
      CREATE TABLE IF NOT EXISTS people (
        id TEXT PRIMARY KEY,
        name TEXT,
        thumbnail_path TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS face_assignments (
        asset_id TEXT NOT NULL,
        face_index INTEGER NOT NULL,
        person_id TEXT NOT NULL,
        confidence REAL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (asset_id, face_index),
        FOREIGN KEY(asset_id) REFERENCES assets(id),
        FOREIGN KEY(person_id) REFERENCES people(id)
      );

      CREATE TABLE IF NOT EXISTS folder_history (
        path TEXT PRIMARY KEY,
        last_scanned_at TEXT DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS processing_issues (
        id TEXT PRIMARY KEY,
        asset_id TEXT NOT NULL,
        job_id TEXT,
        task TEXT NOT NULL, -- 'preview', 'detection', 'recognition'
        severity TEXT NOT NULL, -- 'warning', 'fatal'
        message TEXT,
        details TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(asset_id) REFERENCES assets(id)
      );

      CREATE TABLE IF NOT EXISTS task_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        media_id TEXT NOT NULL,
        pipeline_stage TEXT NOT NULL,
        status TEXT DEFAULT 'pending', -- 'pending', 'processing', 'completed', 'failed'
        priority INTEGER DEFAULT 0,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(media_id, pipeline_stage),
        FOREIGN KEY(media_id) REFERENCES assets(id)
      );

      CREATE INDEX IF NOT EXISTS idx_assets_path ON assets(original_path);
      CREATE INDEX IF NOT EXISTS idx_derived_task ON derived_results(task);
      CREATE INDEX IF NOT EXISTS idx_assignments_person ON face_assignments(person_id);
      CREATE INDEX IF NOT EXISTS idx_issues_asset ON processing_issues(asset_id);
      CREATE INDEX IF NOT EXISTS idx_task_queue_status_priority ON task_queue(status, priority DESC);
    `);

    // Migrations for existing tables
    try { this.db.prepare("ALTER TABLE assets ADD COLUMN width INTEGER").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE assets ADD COLUMN height INTEGER").run(); } catch (e) { }

    // Jobs migrations
    try { this.db.prepare("ALTER TABLE jobs RENAME COLUMN type TO stage").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN started_at TEXT").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN finished_at TEXT").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN total_items INTEGER DEFAULT 0").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN processed_items INTEGER DEFAULT 0").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN error_count INTEGER DEFAULT 0").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN current_item_path TEXT").run(); } catch (e) { }
    try { this.db.prepare("ALTER TABLE jobs ADD COLUMN throughput_ips REAL DEFAULT 0").run(); } catch (e) { }

    // Resume uncompleted tasks on application restart
    try {
      this.db.prepare("UPDATE task_queue SET status = 'pending' WHERE status = 'processing'").run();
    } catch (e) {
      // table might not exist on extremely weird edge cases before commit, ignore
    }
  }

  public getDb() {
    return this.db;
  }
}

import { createHash } from 'node:crypto';
import { createReadStream, statSync } from 'node:fs';
import sharp from 'sharp';

export async function hashFile(filePath: string): Promise<string> {
    return new Promise((resolve, reject) => {
        const hash = createHash('sha256');
        const input = createReadStream(filePath);
        input.on('error', reject);
        input.on('data', chunk => hash.update(chunk));
        input.on('end', () => resolve(hash.digest('hex')));
    });
}

export function getFileStats(filePath: string) {
    return statSync(filePath);
}

export async function getExifData(filePath: string) {
    try {
        const metadata = await sharp(filePath).metadata();
        const isRotated = metadata.orientation && metadata.orientation >= 5;
        return {
            width: isRotated ? metadata.height : metadata.width,
            height: isRotated ? metadata.width : metadata.height,
            exif: metadata.exif // Raw buffer, strictly we might want to parse this, but sharp provides some parsed fields too
        };
    } catch (e) {
        return null;
    }
}

import { DatabaseManager } from '../db';
import { cosineSimilarity } from '../math-utils';
import { v4 as uuidv4 } from 'uuid';
import { EventBus } from '../events/bus';
import sharp from 'sharp';
import { join, dirname } from 'node:path';
import { existsSync, mkdirSync } from 'node:fs';

export async function runFaceClusteringJob(
    jobId: string,
    dbManager: DatabaseManager,
    eventBus: EventBus
) {
    const db = dbManager.getDb();
    const activeJobId = `cluster-batch-${Date.now()}`;

    eventBus.emit({
        type: 'JobStarted',
        jobId: activeJobId,
        pipelineStage: 'analysis'
    });

    // 1. Load all embeddings
    // We need to know which asset and which face index each embedding belongs to.
    const rows = db.prepare(`
        SELECT asset_id, data 
        FROM derived_results 
        WHERE task = 'face_recognition'
    `).all() as any[];

    let allFaces: { assetId: string, faceIndex: number, embedding: number[] }[] = [];

    for (const row of rows) {
        try {
            const data = JSON.parse(row.data);
            if (data.embeddings && Array.isArray(data.embeddings)) {
                data.embeddings.forEach((emb: number[] | null, index: number) => {
                    if (emb) {
                        allFaces.push({
                            assetId: row.asset_id,
                            faceIndex: index,
                            embedding: emb
                        });
                    }
                });
            }
        } catch (e) {
            console.error('Error parsing embedding data:', e);
        }
    }

    if (allFaces.length === 0) {
        eventBus.emit({ type: 'JobCompleted', jobId: activeJobId, pipelineStage: 'analysis' });
        return;
    }

    // 2. Simple Agglomerative Clustering
    const THRESHOLD = 0.65;
    const clusters: number[][] = allFaces.map((_, i) => [i]);

    type Cluster = {
        id: string; // Temp ID
        faces: number[]; // Indices into allFaces
        centroid: number[];
    };

    // Naive re-clustering each time (MVP)
    // Wipe existing?
    const activeClusters: Cluster[] = [];

    for (let i = 0; i < allFaces.length; i++) {
        const face = allFaces[i];
        let bestMatch: Cluster | null = null;
        let bestSim = -1;

        for (const cluster of activeClusters) {
            const sim = cosineSimilarity(face.embedding, cluster.centroid);
            if (sim > THRESHOLD && sim > bestSim) {
                bestSim = sim;
                bestMatch = cluster;
            }
        }

        if (bestMatch) {
            bestMatch.faces.push(i);
            const n = bestMatch.faces.length;
            for (let k = 0; k < 512; k++) {
                bestMatch.centroid[k] = (bestMatch.centroid[k] * (n - 1) + face.embedding[k]) / n;
            }
        } else {
            activeClusters.push({
                id: uuidv4(),
                faces: [i],
                centroid: [...face.embedding]
            });
        }
    }

    // 3. Save to DB
    const wipe = db.transaction(() => {
        db.prepare("DELETE FROM face_assignments").run();
        db.prepare("DELETE FROM people").run();
    });
    wipe();

    const insertPerson = db.prepare("INSERT INTO people (id, name, thumbnail_path) VALUES (?, ?, ?)");
    const insertAssignment = db.prepare("INSERT INTO face_assignments (asset_id, face_index, person_id, confidence) VALUES (?, ?, ?, ?)");

    const saveTransaction = db.transaction(() => {
        let pCount = 0;
        for (const cluster of activeClusters) {
            pCount++;
            const name = `Person ${pCount}`;

            insertPerson.run(cluster.id, name, null);

            for (const faceIdx of cluster.faces) {
                const face = allFaces[faceIdx];
                const conf = cosineSimilarity(face.embedding, cluster.centroid);
                insertAssignment.run(face.assetId, face.faceIndex, cluster.id, conf);
            }

            eventBus.emit({
                type: 'FaceClusteringUpdated',
                clusterId: cluster.id
            });
        }
    });

    saveTransaction();

    // 4. Generate Face-Crop Thumbnails for each person
    const libraryDir = dirname(db.name);
    const previewsDir = join(libraryDir, 'previews');
    if (!existsSync(previewsDir)) mkdirSync(previewsDir, { recursive: true });

    console.error(`[Clustering] Generating thumbnails for ${activeClusters.length} people...`);
    let thumbDone = 0;

    for (const cluster of activeClusters) {
        try {
            const bestFace = db.prepare(`
                SELECT asset_id, face_index 
                FROM face_assignments 
                WHERE person_id = ? 
                ORDER BY confidence DESC 
                LIMIT 1
            `).get(cluster.id) as { asset_id: string, face_index: number } | undefined;

            if (bestFace) {
                const asset = db.prepare('SELECT original_path, width, height FROM assets WHERE id = ?').get(bestFace.asset_id) as { original_path: string, width: number, height: number } | undefined;
                const detection = db.prepare("SELECT data FROM derived_results WHERE asset_id = ? AND task = 'face_detection'").get(bestFace.asset_id) as { data: string } | undefined;

                if (asset && detection && asset.width && asset.height) {
                    const data = JSON.parse(detection.data);
                    const face = data.faces[bestFace.face_index];
                    if (face) {
                        const box = face.box; // [x1, y1, x2, y2]
                        const fw = box[2] - box[0];
                        const fh = box[3] - box[1];
                        const cx = (box[0] + box[2]) / 2;
                        const cy = (box[1] + box[3]) / 2;

                        // Normalize: 1.5x padded square crop
                        const cropSize = Math.max(fw, fh) * 1.5;
                        let x1 = cx - cropSize / 2;
                        let y1 = cy - cropSize / 2;
                        let x2 = cx + cropSize / 2;
                        let y2 = cy + cropSize / 2;

                        // Clamp and keep square if possible
                        if (x1 < 0) { x2 -= x1; x1 = 0; }
                        if (y1 < 0) { y2 -= y1; y1 = 0; }
                        if (x2 > 1) { x1 -= (x2 - 1); x2 = 1; }
                        if (y2 > 1) { y1 -= (y2 - 1); y2 = 1; }
                        x1 = Math.max(0, x1); y1 = Math.max(0, y1);
                        x2 = Math.min(1, x2); y2 = Math.min(1, y2);

                        const outPath = join(previewsDir, `person-${cluster.id}.webp`);

                        const cropLeft = Math.floor(x1 * asset.width);
                        const cropTop = Math.floor(y1 * asset.height);
                        const cropWidth = Math.floor((x2 - x1) * asset.width);
                        const cropHeight = Math.floor((y2 - y1) * asset.height);

                        // Ensure dimensions are valid for sharp
                        if (cropWidth > 5 && cropHeight > 5) {
                            await sharp(asset.original_path)
                                .rotate()
                                .extract({
                                    left: cropLeft,
                                    top: cropTop,
                                    width: cropWidth,
                                    height: cropHeight
                                })
                                .resize(256, 256)
                                .webp({ quality: 85 })
                                .toFile(outPath);

                            db.prepare("UPDATE people SET thumbnail_path = ? WHERE id = ?").run(outPath, cluster.id);
                        }
                    }
                }
            }
        } catch (e) {
            console.error(`Failed to generate thumbnail for person ${cluster.id}:`, e);
        }

        thumbDone++;
        if (thumbDone % 10 === 0 || thumbDone === activeClusters.length) {
            eventBus.emit({
                type: 'JobProgress',
                jobId: activeJobId,
                processedItems: thumbDone,
                totalItems: activeClusters.length,
                currentItemPath: `Person ${thumbDone}`
            });
        }
    }

    eventBus.emit({
        type: 'JobCompleted',
        jobId: activeJobId,
        pipelineStage: 'analysis'
    });
}

import { parentPort } from 'node:worker_threads';
import path from 'node:path';
import { DatabaseManager } from '../db';
import * as ort from 'onnxruntime-node';
import sharp from 'sharp';
import { join } from 'node:path';
import { v4 as uuidv4 } from 'uuid';
import { EventBus } from '../events/bus';

const MODEL_FILENAME = 'det_10g.onnx';
let MODEL_PATH = join(path.dirname(process.execPath), 'models', MODEL_FILENAME);

if (!require('fs').existsSync(MODEL_PATH)) {
    MODEL_PATH = join(__dirname, '../../models', MODEL_FILENAME);
}

// RetinaFace / Buffalo_L Constants
const INPUT_WIDTH = 640;
const INPUT_HEIGHT = 640;
const STEPS = [8, 16, 32];
const MIN_SIZES = [[16, 32], [64, 128], [256, 512]];
const VARIANCE = [0.1, 0.2];

class FaceDetector {
    private session: ort.InferenceSession | null = null;
    private anchors: number[][] = [];

    async init() {
        if (this.session) return;
        let usableModelPath = MODEL_PATH;
        if (MODEL_PATH.includes('snapshot')) {
            const tmpDir = require('os').tmpdir();
            const tmpPath = join(tmpDir, MODEL_FILENAME);
            if (!require('fs').existsSync(tmpPath)) {
                require('fs').copyFileSync(MODEL_PATH, tmpPath);
            }
            usableModelPath = tmpPath;
        }

        const options: ort.InferenceSession.SessionOptions = { logSeverityLevel: 3 };
        this.session = await ort.InferenceSession.create(usableModelPath, options);
        this.generateAnchors();
    }

    private generateAnchors() {
        this.anchors = [];
        const featureMaps = STEPS.map(step => [Math.ceil(INPUT_HEIGHT / step), Math.ceil(INPUT_WIDTH / step)]);
        featureMaps.forEach((fmap, k) => {
            const minSizes = MIN_SIZES[k];
            for (let i = 0; i < fmap[0]; i++) {
                for (let j = 0; j < fmap[1]; j++) {
                    for (const minSize of minSizes) {
                        const s_kx = minSize / INPUT_WIDTH;
                        const s_ky = minSize / INPUT_HEIGHT;
                        const dense_cx = (j + 0.5) * STEPS[k] / INPUT_WIDTH;
                        const dense_cy = (i + 0.5) * STEPS[k] / INPUT_HEIGHT;
                        this.anchors.push([dense_cx, dense_cy, s_kx, s_ky]);
                    }
                }
            }
        });
    }

    async detect(imagePath: string): Promise<any[]> {
        if (!this.session) throw new Error('Model not loaded');
        const image = sharp(imagePath);
        const metadata = await image.metadata();
        const { width: origW, height: origH } = metadata;
        if (!origW || !origH) throw new Error('Bad image');

        const buffer = await image
            .resize(INPUT_WIDTH, INPUT_HEIGHT, { fit: 'fill' })
            .removeAlpha()
            .raw()
            .toBuffer();

        const float32Data = new Float32Array(3 * INPUT_HEIGHT * INPUT_WIDTH);
        for (let i = 0; i < INPUT_HEIGHT * INPUT_WIDTH; i++) {
            float32Data[i] = (buffer[i * 3] - 127.5) / 128.0;
            float32Data[i + INPUT_HEIGHT * INPUT_WIDTH] = (buffer[i * 3 + 1] - 127.5) / 128.0;
            float32Data[i + 2 * INPUT_HEIGHT * INPUT_WIDTH] = (buffer[i * 3 + 2] - 127.5) / 128.0;
        }

        const tensor = new ort.Tensor('float32', float32Data, [1, 3, INPUT_HEIGHT, INPUT_WIDTH]);
        const results = await this.session.run({ 'input.1': tensor });

        try {
            const scores = Float32Array.from([
                ...(results['448'].data as Float32Array),
                ...(results['471'].data as Float32Array),
                ...(results['494'].data as Float32Array)
            ]);
            const boxes = Float32Array.from([
                ...(results['451'].data as Float32Array),
                ...(results['474'].data as Float32Array),
                ...(results['497'].data as Float32Array)
            ]);
            const landmarks = Float32Array.from([
                ...(results['454'].data as Float32Array),
                ...(results['477'].data as Float32Array),
                ...(results['500'].data as Float32Array)
            ]);

            return this.postProcess(scores, boxes, landmarks, origW, origH);
        } catch (e) {
            return [];
        }
    }

    private postProcess(scores: Float32Array, boxes: Float32Array, landmarks: Float32Array, origW: number, origH: number) {
        const threshold = 0.5;
        const candidates: any[] = [];
        for (let i = 0; i < this.anchors.length; i++) {
            const score = scores[i];
            if (score > threshold) {
                const anchor = this.anchors[i];
                const dx = boxes[i * 4];
                const dy = boxes[i * 4 + 1];
                const dw = boxes[i * 4 + 2];
                const dh = boxes[i * 4 + 3];

                const cx = anchor[0] + dx * VARIANCE[0] * anchor[2];
                const cy = anchor[1] + dy * VARIANCE[0] * anchor[3];
                const w = anchor[2] * Math.exp(dw * VARIANCE[1]);
                const h = anchor[3] * Math.exp(dh * VARIANCE[1]);

                const x1 = cx - w / 2;
                const y1 = cy - h / 2;
                const x2 = cx + w / 2;
                const y2 = cy + h / 2;

                const land = [];
                for (let k = 0; k < 5; k++) {
                    const ldx = landmarks[i * 10 + k * 2];
                    const ldy = landmarks[i * 10 + k * 2 + 1];
                    const lx = anchor[0] + ldx * VARIANCE[0] * anchor[2];
                    const ly = anchor[1] + ldy * VARIANCE[0] * anchor[3];
                    land.push({ x: lx, y: ly });
                }

                candidates.push({
                    score,
                    box: [
                        Math.max(0, Math.min(1, x1)),
                        Math.max(0, Math.min(1, y1)),
                        Math.max(0, Math.min(1, x2)),
                        Math.max(0, Math.min(1, y2))
                    ],
                    landmarks: land
                });
            }
        }
        return this.nms(candidates);
    }

    private nms(candidates: any[]) {
        candidates.sort((a, b) => b.score - a.score);
        const kept: any[] = [];
        while (candidates.length > 0) {
            const best = candidates.shift();
            kept.push(best);
            for (let i = candidates.length - 1; i >= 0; i--) {
                if (this.iou(best.box, candidates[i].box) > 0.4) {
                    candidates.splice(i, 1);
                }
            }
        }
        return kept;
    }

    private iou(boxA: number[], boxB: number[]) {
        const xA = Math.max(boxA[0], boxB[0]);
        const yA = Math.max(boxA[1], boxB[1]);
        const xB = Math.min(boxA[2], boxB[2]);
        const yB = Math.min(boxA[3], boxB[3]);
        const interArea = Math.max(0, xB - xA) * Math.max(0, yB - yA);
        const boxAArea = (boxA[2] - boxA[0]) * (boxA[3] - boxA[1]);
        const boxBArea = (boxB[2] - boxB[0]) * (boxB[3] - boxB[1]);
        return interArea / (boxAArea + boxBArea - interArea);
    }
}

export async function runFaceDetectionJob(
    targetInput: string | string[],
    dbManager: DatabaseManager,
    eventBus: EventBus
) {
    const db = dbManager.getDb();

    // Determine scope
    let assets: any[] = [];

    if (Array.isArray(targetInput) && targetInput.length > 0) {
        // Optimised batch fetch
        const placeholders = targetInput.map(() => '?').join(',');
        assets = db.prepare(`SELECT id, original_path FROM assets WHERE id IN (${placeholders})`).all(...targetInput) as any[];
    } else if (typeof targetInput === 'string' && !targetInput.startsWith('job-')) {
        // Single ID
        assets = db.prepare('SELECT id, original_path FROM assets WHERE id = ?').all(targetInput) as any[];
    } else {
        // Fallback or "Scanning" mode - find all pending
        assets = db.prepare(`
            SELECT id, original_path 
            FROM assets 
            WHERE id NOT IN (
                SELECT asset_id FROM derived_results WHERE task = 'face_detection'
            )
        `).all() as any[];
    }

    if (assets.length === 0) return;

    const detector = new FaceDetector();
    try {
        await detector.init();
    } catch (e: any) {
        console.error('Failed to init detector', e);
        return;
    }

    const jobId = `detect-batch-${Date.now()}`;
    const totalItems = assets.length;
    let processed = 0;
    let errors = 0;
    const startTime = Date.now();
    let lastReportTime = startTime;

    eventBus.emit({
        type: 'JobStarted',
        jobId: jobId,
        pipelineStage: 'detection'
    });

    const reportProgress = (currentItemPath?: string, force = false) => {
        const now = Date.now();
        if (!force && now - lastReportTime < 500) return;

        const elapsedSec = (now - startTime) / 1000;
        const throughputIps = elapsedSec > 0 ? processed / elapsedSec : 0;

        eventBus.emit({
            type: 'JobProgress',
            jobId: jobId,
            processedItems: processed,
            totalItems,
            currentItemPath,
            throughputIps,
            errorCount: errors
        });

        lastReportTime = now;
    };

    const insertStmt = db.prepare(`
        INSERT INTO derived_results (id, asset_id, task, provider, model_version, data)
        VALUES (?, ?, 'face_detection', 'onnx_retina_10g', '1.0', ?)
    `);

    for (const asset of assets) {
        // Run synchronously-ish
        try {
            const faces = await detector.detect(asset.original_path);

            const resultData = JSON.stringify({
                faces: faces.map(f => ({
                    id: uuidv4(), // Assign ID to each face
                    box: f.box,
                    score: f.score,
                    landmarks: f.landmarks
                }))
            });

            insertStmt.run(uuidv4(), asset.id, resultData);

            eventBus.emit({
                type: 'FacesDetected',
                mediaId: asset.id,
                faceCount: faces.length
            });

            processed++;
            reportProgress(asset.original_path);

        } catch (e: any) {
            console.error(`Error detecting faces for ${asset.original_path}:`, e);
            errors++;

            try {
                db.prepare(`
                    INSERT INTO processing_issues (id, asset_id, job_id, task, severity, message)
                    VALUES (?, ?, ?, 'detection', 'fatal', ?)
                `).run(uuidv4(), asset.id, jobId, e.message);
            } catch (dbErr) {
                console.error('Failed to log processing issue:', dbErr);
            }

            eventBus.emit({
                type: 'JobFailed',
                jobId: 'detection-' + asset.id,
                severity: 'warning',
                reason: e.message
            });
            processed++;
            reportProgress();
        }
    }

    reportProgress(undefined, true);
    eventBus.emit({
        type: 'JobCompleted',
        jobId: jobId,
        pipelineStage: 'detection'
    });
}

import { DatabaseManager } from '../db';
import { join, dirname, basename } from 'node:path';
import { existsSync, mkdirSync } from 'node:fs';
import sharp from 'sharp';
import { EventBus } from '../events/bus';

const PREVIEW_SIZES = {
    'thumbnail': 450,
    'large': 1080
};

// Increment this version whenever the thumbnail generation algorithm changes.
// It will invalidate older thumbnails and regenerate them during the next job run.
export const CURRENT_PREVIEW_VERSION = 3;

export async function runPreviewJob(
    mediaIds: string[],
    dbManager: DatabaseManager,
    eventBus: EventBus
) {
    const db = dbManager.getDb();
    const libraryDir = dirname(db.name);
    const previewsDir = join(libraryDir, 'previews');

    if (!existsSync(previewsDir)) {
        mkdirSync(previewsDir, { recursive: true });
    }

    const jobId = `preview-batch-${Date.now()}`;
    const totalItems = mediaIds.length;
    let processed = 0;
    let errors = 0;
    const startTime = Date.now();
    let lastReportTime = startTime;

    eventBus.emit({
        type: 'JobStarted',
        jobId: jobId,
        pipelineStage: 'previews'
    });

    const reportProgress = (currentItemPath?: string, force = false) => {
        const now = Date.now();
        if (!force && now - lastReportTime < 500) return; // Throttle 500ms

        const elapsedSec = (now - startTime) / 1000;
        const throughputIps = elapsedSec > 0 ? processed / elapsedSec : 0;

        eventBus.emit({
            type: 'JobProgress',
            jobId: jobId,
            processedItems: processed,
            totalItems,
            currentItemPath,
            throughputIps,
            errorCount: errors
        });

        lastReportTime = now;
    };

    // Process provided mediaIds
    for (const mediaId of mediaIds) {
        try {
            const asset = db.prepare('SELECT id, original_path FROM assets WHERE id = ?').get(mediaId) as { id: string, original_path: string } | undefined;

            if (!asset) {
                console.warn(`Asset ${mediaId} not found during preview generation`);
                errors++;
                processed++;
                reportProgress();
                continue;
            }

            // Construct expected path
            const thumbPath = join(previewsDir, `${asset.id}-thumbnail.webp`);

            // Check if already has thumbnails matching the current version
            const existing = db.prepare('SELECT count(*) as count FROM previews WHERE asset_id = ? AND version >= ?').get(asset.id, CURRENT_PREVIEW_VERSION) as any;
            if (existing.count >= Object.keys(PREVIEW_SIZES).length) {
                // Already done
                eventBus.emit({
                    type: 'PreviewGenerated',
                    mediaId: asset.id,
                    path: thumbPath
                });
                processed++;
                reportProgress(asset.original_path);
                continue;
            }

            // Generate
            for (const [sizeName, width] of Object.entries(PREVIEW_SIZES)) {
                const filename = `${asset.id}-${sizeName}.webp`;
                const outPath = join(previewsDir, filename);

                // Even if file exists, we regenerate if version mismatch (handled by existing.count check above)
                // BUT we should verify file existence before skipping regenerate
                if (!existsSync(outPath) || existing.count < Object.keys(PREVIEW_SIZES).length) {
                    await sharp(asset.original_path)
                        .rotate() // Respect EXIF orientation
                        .resize(width, null, {
                            withoutEnlargement: true,
                            fit: 'inside'
                        })
                        .webp({ effort: 4, quality: 80 })
                        .toFile(outPath);
                }

                db.prepare(`
                    INSERT OR REPLACE INTO previews (asset_id, size, path, version) 
                    VALUES (?, ?, ?, ?)
                `).run(asset.id, sizeName, outPath, CURRENT_PREVIEW_VERSION);
            }

            eventBus.emit({
                type: 'PreviewGenerated',
                mediaId: asset.id,
                path: thumbPath
            });

            processed++;
            reportProgress(asset.original_path);

        } catch (e: any) {
            console.error(`Failed preview for ${mediaId}:`, e);
            errors++;


            try {
                db.prepare(`
                    INSERT INTO processing_issues (id, asset_id, job_id, task, severity, message)
                    VALUES (?, ?, ?, 'preview', 'fatal', ?)
                `).run(require('uuid').v4(), mediaId, jobId, e.message);
            } catch (dbErr) {
                console.error('Failed to log processing issue:', dbErr);
            }

            eventBus.emit({
                type: 'PreviewFailed',
                mediaId: mediaId,
                severity: 'error'
            });
            processed++;
            reportProgress();
        }
    }

    reportProgress(undefined, true);

    eventBus.emit({
        type: 'JobCompleted',
        jobId: jobId
    });
}

import { parentPort } from 'node:worker_threads';
import path from 'node:path';
import { DatabaseManager } from '../db';
import * as ort from 'onnxruntime-node';
import sharp from 'sharp';
import { join } from 'node:path';
import { v4 as uuidv4 } from 'uuid';
import { EventBus } from '../events/bus';

const MODEL_FILENAME = 'w600k_r50.onnx';
let MODEL_PATH = join(path.dirname(process.execPath), 'models', MODEL_FILENAME);

if (!require('fs').existsSync(MODEL_PATH)) {
    MODEL_PATH = join(__dirname, '../../models', MODEL_FILENAME);
}

class FaceRecogniser {
    private session: ort.InferenceSession | null = null;

    async init() {
        if (this.session) return;
        let usableModelPath = MODEL_PATH;
        if (MODEL_PATH.includes('snapshot')) {
            const tmpDir = require('os').tmpdir();
            const tmpPath = join(tmpDir, MODEL_FILENAME);
            if (!require('fs').existsSync(tmpPath)) {
                require('fs').copyFileSync(MODEL_PATH, tmpPath);
            }
            usableModelPath = tmpPath;
        }
        const options: ort.InferenceSession.SessionOptions = { logSeverityLevel: 3 };
        this.session = await ort.InferenceSession.create(usableModelPath, options);
    }

    async computeEmbedding(imagePath: string, box: number[], landmarks: { x: number, y: number }[]): Promise<number[] | null> {
        if (!this.session) throw new Error('Model not loaded');

        const image = sharp(imagePath);
        const metadata = await image.metadata();
        const iw = metadata.width || 0;
        const ih = metadata.height || 0;

        let x1 = box[0] * iw;
        let y1 = box[1] * ih;
        let x2 = box[2] * iw;
        let y2 = box[3] * ih;

        let bw = x2 - x1;
        let bh = y2 - y1;
        const cx = x1 + bw / 2;
        const cy = y1 + bh / 2;
        const size = Math.max(bw, bh) * 1.3;

        x1 = Math.max(0, cx - size / 2);
        y1 = Math.max(0, cy - size / 2);
        bw = size;
        bh = size;

        if (x1 + bw > iw) bw = iw - x1;
        if (y1 + bh > ih) bh = ih - y1;

        const buffer = await image
            .extract({ left: Math.round(x1), top: Math.round(y1), width: Math.round(bw), height: Math.round(bh) })
            .resize(112, 112, { fit: 'fill' })
            .removeAlpha()
            .raw()
            .toBuffer();

        const float32Data = new Float32Array(3 * 112 * 112);
        for (let i = 0; i < 112 * 112; i++) {
            float32Data[i] = (buffer[i * 3] - 127.5) / 128.0;
            float32Data[i + 112 * 112] = (buffer[i * 3 + 1] - 127.5) / 128.0;
            float32Data[i + 2 * 112 * 112] = (buffer[i * 3 + 2] - 127.5) / 128.0;
        }

        const tensor = new ort.Tensor('float32', float32Data, [1, 3, 112, 112]);
        const results = await this.session.run({ 'input.1': tensor });
        const outputKey = Object.keys(results)[0];
        const embedding = results[outputKey].data as Float32Array;

        return Array.from(embedding);
    }
}

export async function runFaceRecognitionJob(
    targetInput: string | string[],
    dbManager: DatabaseManager,
    eventBus: EventBus
) {
    const db = dbManager.getDb();

    // Determine scope
    let assets: any[] = [];

    if (Array.isArray(targetInput) && targetInput.length > 0) {
        const placeholders = targetInput.map(() => '?').join(',');
        assets = db.prepare(`
            SELECT d.asset_id, d.data, a.original_path 
            FROM derived_results d
            JOIN assets a ON a.id = d.asset_id
            WHERE d.task = 'face_detection' AND a.id IN (${placeholders})
        `).all(...targetInput) as any[];
    } else if (typeof targetInput === 'string' && !targetInput.includes('sweep') && !targetInput.includes('auto')) {
        assets = db.prepare(`
            SELECT d.asset_id, d.data, a.original_path 
            FROM derived_results d
            JOIN assets a ON a.id = d.asset_id
            WHERE d.task = 'face_detection' AND a.id = ?
        `).all(targetInput) as any[];
    } else {
        // Find assets with detection but no recognition
        assets = db.prepare(`
            SELECT d.asset_id, d.data, a.original_path 
            FROM derived_results d
            JOIN assets a ON a.id = d.asset_id
            WHERE d.task = 'face_detection'
            AND d.asset_id NOT IN (
                SELECT asset_id FROM derived_results WHERE task = 'face_recognition'
            )
        `).all() as any[];
    }

    if (assets.length === 0) return;

    const recogniser = new FaceRecogniser();
    await recogniser.init();

    const insertStmt = db.prepare(`
        INSERT INTO derived_results (id, asset_id, task, provider, model_version, data)
        VALUES (?, ?, 'face_recognition', 'onnx_arcface_r50', '1.0', ?)
    `);

    const activeJobId = `recog-batch-${Date.now()}`;
    const totalItems = assets.length;
    let processed = 0;
    let errors = 0;
    const startTime = Date.now();
    let lastReportTime = startTime;

    eventBus.emit({
        type: 'JobStarted',
        jobId: activeJobId,
        pipelineStage: 'recognition'
    });

    const reportProgress = (currentItemPath?: string, force = false) => {
        const now = Date.now();
        if (!force && now - lastReportTime < 500) return;

        const elapsedSec = (now - startTime) / 1000;
        const throughputIps = elapsedSec > 0 ? processed / elapsedSec : 0;

        eventBus.emit({
            type: 'JobProgress',
            jobId: activeJobId,
            processedItems: processed,
            totalItems,
            currentItemPath,
            throughputIps,
            errorCount: errors
        });

        lastReportTime = now;
    };

    for (const row of assets) {
        try {
            const detectionData = JSON.parse(row.data);
            const faces = detectionData.faces || [];

            // Should contain 'id' now from updated detect_faces

            const embeddings = [];

            for (const face of faces) {
                if (face.box && face.landmarks) {
                    try {
                        const emb = await recogniser.computeEmbedding(row.original_path, face.box, face.landmarks);
                        embeddings.push(emb);

                        if (emb && face.id) {
                            eventBus.emit({
                                type: 'FaceEmbeddingGenerated',
                                mediaId: row.asset_id,
                                faceId: face.id
                            });
                        }
                    } catch (e) {
                        console.error('Recog error:', e);
                        embeddings.push(null);
                    }
                } else {
                    embeddings.push(null);
                }
            }

            insertStmt.run(uuidv4(), row.asset_id, JSON.stringify({ embeddings }));
            processed++;
            reportProgress(row.original_path);
        } catch (e: any) {
            console.error(`Error recognizing faces for ${row.asset_id}:`, e);
            errors++;
            processed++;
            reportProgress(row.original_path);
        }
    }

    reportProgress(undefined, true);
    eventBus.emit({
        type: 'JobCompleted',
        jobId: activeJobId,
        pipelineStage: 'recognition'
    });
}

import { DatabaseManager } from '../db';
import { hashFile, getFileStats, getExifData } from '../file-utils';
import { join, extname } from 'node:path';
import { readdirSync, statSync } from 'node:fs';
import { v4 as uuidv4 } from 'uuid';
import { EventBus } from '../events/bus';

const IMAGE_EXTENSIONS = new Set(['.jpg', '.jpeg', '.png', '.webp', '.gif', '.heic']);

export async function runScanJob(
    jobId: string,
    rootPath: string,
    dbManager: DatabaseManager,
    eventBus: EventBus,
    signal?: AbortSignal
) {
    console.error(`[ScanJob] Starting for ${rootPath}`);
    const db = dbManager.getDb();
    let processed = 0;
    let errors = 0;

    // 1. Initial Count (Quick recursive scan for total)
    console.error(`[ScanJob] Counting files...`);
    let totalToProcess = 0;
    const countStack = [rootPath];
    while (countStack.length > 0) {
        const dir = countStack.pop()!;
        try {
            const files = readdirSync(dir);
            for (const file of files) {
                const fullPath = join(dir, file);
                try {
                    const stats = statSync(fullPath);
                    if (stats.isDirectory()) {
                        countStack.push(fullPath);
                    } else {
                        const ext = extname(fullPath).toLowerCase();
                        if (IMAGE_EXTENSIONS.has(ext)) {
                            totalToProcess++;
                        }
                    }
                } catch (e) { }
            }
        } catch (e) { }
    }
    console.error(`[ScanJob] Total files found: ${totalToProcess}`);

    const stack = [rootPath];

    const startTime = Date.now();
    let lastReportTime = startTime;

    // Emit initial event with total
    eventBus.emit({
        type: 'JobStarted',
        jobId: jobId,
        pipelineStage: 'scan',
        totalItems: totalToProcess
    });

    const reportProgress = (currentItemPath?: string, force = false) => {
        const now = Date.now();
        if (!force && now - lastReportTime < 500) return; // Throttle to 500ms

        const elapsedSec = (now - startTime) / 1000;
        const throughputIps = elapsedSec > 0 ? processed / elapsedSec : 0;

        eventBus.emit({
            type: 'JobProgress',
            jobId: jobId,
            processedItems: processed,
            currentItemPath,
            throughputIps,
            errorCount: errors
        });

        lastReportTime = now;
    };

    while (stack.length > 0) {
        // console.error(`[ScanJob] Stack size: ${stack.length}`);
        if (signal?.aborted) {
            console.log(`Job ${jobId} cancelled.`);
            eventBus.emit({
                type: 'JobFailed',
                jobId: jobId,
                severity: 'warning',
                reason: 'Cancelled by user'
            });
            reportProgress(undefined, true);
            return;
        }
        const dir = stack.pop()!;
        try {
            const files = readdirSync(dir);
            for (const file of files) {
                const fullPath = join(dir, file);
                try {
                    const stats = statSync(fullPath);
                    if (stats.isDirectory()) {
                        stack.push(fullPath);
                    } else {
                        const ext = extname(fullPath).toLowerCase();
                        if (IMAGE_EXTENSIONS.has(ext)) {
                            // Check if exists
                            const exists = db.prepare('SELECT id FROM assets WHERE original_path = ?').get(fullPath) as { id: string } | undefined;

                            let mediaId = exists?.id;

                            if (!exists) {
                                mediaId = uuidv4();
                                const size = stats.size;
                                const hash = await hashFile(fullPath);
                                const exif = await getExifData(fullPath);
                                const width = exif?.width || 0;
                                const height = exif?.height || 0;
                                const exifDate = new Date(stats.birthtime).toISOString();

                                db.prepare('INSERT INTO assets (id, original_path, file_hash, file_size, width, height, exif_datetime, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
                                    .run(mediaId, fullPath, hash, size, width, height, exifDate, new Date().toISOString());

                                eventBus.emit({
                                    type: 'MediaDiscovered',
                                    mediaId: mediaId,
                                    filePath: fullPath,
                                    width: width,
                                    height: height,
                                    scanSessionId: jobId
                                });
                            } else {
                                // Exists. Check for fatal issues before re-triggering
                                const fatalIssue = db.prepare("SELECT id FROM processing_issues WHERE asset_id = ? AND severity = 'fatal'").get(mediaId);
                                if (fatalIssue) {
                                    console.warn(`[Scanner] Skipping ${fullPath} due to recorded fatal processing issue.`);
                                    processed++;
                                    reportProgress(fullPath);
                                    continue;
                                }

                                // Check if it's incomplete (missing preview or face detection)
                                const dr = db.prepare('SELECT id FROM derived_results WHERE asset_id = ? AND task = ?').get(mediaId, 'face_detection');
                                const assetRecord = db.prepare('SELECT p.path as preview_path, a.width, a.height FROM assets a LEFT JOIN previews p ON a.id = p.asset_id WHERE a.id = ?').get(mediaId) as { preview_path: string | null, width: number, height: number };

                                if (!assetRecord?.preview_path || !dr) {
                                    // Missing critical post-processing, re-emit discovery to trigger pipeline
                                    eventBus.emit({
                                        type: 'MediaDiscovered',
                                        mediaId: mediaId!,
                                        filePath: fullPath,
                                        width: assetRecord.width,
                                        height: assetRecord.height,
                                        scanSessionId: jobId
                                    });
                                }
                            }

                            processed++;
                            reportProgress(fullPath);
                        }
                    }
                } catch (e: any) {
                    console.error(`Error processing ${fullPath}:`, e);
                    errors++;
                    reportProgress(fullPath);
                }
            }
        } catch (e: any) {
            console.error(`Error reading dir ${dir}:`, e);
            errors++;
            eventBus.emit({
                type: 'JobFailed',
                jobId: jobId,
                severity: 'error',
                reason: e.message
            });
        }
    }

    reportProgress(undefined, true); // Final forced report

    eventBus.emit({
        type: 'JobCompleted',
        jobId: jobId
    });
}

